# create 30x30 patterned test grid and connect same-color tile centers through zero separator gaps
vals=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
g=[[0]*30 for _ in range(30)]
for tr in range(4):
 for tc in range(4):
  y=1+7*tr; x=1+7*tc
  for dy in range(5):
   for dx in range(5): g[y+dy][x+dx]=4
  for dy in range(1,4):
   for dx in range(1,4): g[y+dy][x+dx]=vals[tr][tc]
# horizontal connectors over gaps at tile center row; connect all same colors aligned, only gaps between tile blocks
for tr in range(4):
 for tc in range(3):
  if vals[tr][tc]==vals[tr][tc+1]:
   y=3+7*tr
   for x in range(6+7*tc,8+7*tc): g[y][x]=vals[tr][tc]
# vertical connector gap rows, between tiles
for tc in range(4):
 for tr in range(3):
  if vals[tr][tc]==vals[tr+1][tc]:
   x=3+7*tc
   for y in range(6+7*tr,8+7*tr): g[y][x]=vals[tr][tc]
print('\n'.join(' '.join(map(str,r)) for r in g))

